from sai import Sai

sai = Sai()
session = sai.sessions.create()
turn = session.send(
    "Sign in to the {{vendor}} portal and list the invoices dated in {{month}}.",
    inputs={"vendor": "Acme", "month": "September 2026"},
    output_schema={
        "type": "object",
        "properties": {
            "invoices": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "number": {"type": "string"},
                        "date": {"type": "string", "pattern": r"^\d{4}-\d{2}-\d{2}$"},
                        "total": {"type": "number"},
                    },
                    "required": ["number", "date", "total"],
                },
            }
        },
        "required": ["invoices"],
    },
    success_criteria=[
        {"id": "signed_in", "check": "Sai signed in and saw the invoice list."},
        {
            "id": "all_listed",
            "check": "Every invoice dated in the month is in the answer.",
            "returnEvidence": True,
        },
    ],
    idempotency_key="acme-invoices-2026-09",
    record_trajectory=True,
)
print(turn.id)

# `turn` is what session.send() returned in step 4; events() polls until the turn ends.
for ev in turn.events():
    print(ev.kind, ev.text)

turn = session.send("Find last month's invoices in Downloads and total them")
for ev in turn.events():
    if ev.kind == "step":
        print("  ", ev.text)
    elif ev.kind == "approval":
        turn.respond(ev.approval, "yes")
result = turn.wait()

def decide(approval):
    if approval.is_link_only:
        print("Approve in a browser:", approval.url)
        return None  # a person answers it; keep waiting
    if approval.type == "choice":
        return ("yes", [[q["options"][0]["value"]] for q in approval.questions])
    return "yes"

result = session.run("Clean up the temp folder", on_approval=decide)

result = session.run(
    "Open https://news.ycombinator.com and read the title of the top story.",
    output_schema={"type": "object", "properties": {"title": {"type": "string"}}, "required": ["title"]},
)
if result.ok:
    print(result.record.output["title"])
else:
    print(result.record.reason_code)   # e.g. output_invalid
